class TranslationConfig:
    """Configuration for i18n (L279 style dictionary)."""
    
    def __init__(self, lang_code="en-us", locale_name=None):
        self.lang_code = lang_code if isinstance(lang_code, str) else "en-us"  # Default to English
        self.locale_name = locale_name or f"{lang_code}_locale"

def generate_locale_key(locale: Union[str, Dict], default_lang: str = None) -> str:
    """Generate a unique key for the current locale based on lang and locale name."""
    if isinstance(locale, dict):
        return f"{default_lang}_{locale}"  # e.g., "en-us_english" or "de-de_deutschland"
    else:
        return default_lang + "_" + str(locale)

def get_locale_key(lang_code="en", locale_name=None):
    """Get the translation key for a specific language and locale combination."""
    if isinstance(lang_code, dict):
        # If it's already an object with lang code (e.g., "de-de"), use that directly.
        return f"{lang_code}"  # e.g., "de_de" or "en_US"
    
    key = generate_locale_key(locale=locale_name if locale_name else None, default_lang="default")
    return get_locale_key(lang_code=key)

